const _flow = { sourceVersion: 3 }

const requestable = flow.import("requestable")

function Imports({ input, config, result }) {
  const contacts = requestable.call({ requestable: ".ListContacts", input: { limit: 10 } })
  return { contacts }
}

const rows = []
for (const item of input.items) {
  rows.push({ label: item.label, size: `${item.size}`, large: item.size > 10 })
}
return { rows }

let names = []
names.push("a")
names.push(null)
if (input.reset) {
  names = []
}
return { names }

const byCat = json.map({ valueType: { type: "object" } })
for (const row of input.rows) {
  if (byCat[row.category] == null) {
    byCat[row.category] = { count: 0, total: 0 }
  }
  const g = byCat[row.category]
  g.count++
  g.total += row.amount
}
return { byCat }

if (input.items.length > 2) {
  result.size = "large"
} else if (input.items.length > 0) {
  result.size = "small"
} else {
  result.size = "empty"
}

const actor = input.actor
if (!actor.roles.some(role => role == "OWNER")) {
  return { owner: false }
}
if (Object.keys(input.o).length == 0) {
  return { owner: true, empty: true }
}
return { owner: true }

let n = 0
while (n < 3) {
  n++
}
return { n }

let total = 0
for (const item of input.items) {
  total += item.amount
}
for (const { id } of input.rows) {
  total += id
}
return { total }

const names = json.array({ itemType: { type: "string" } })
for (const key of Object.keys(input.groups)) {
  names.push(key)
}
let total = 0
for (const amount of Object.values(input.groups)) {
  total += amount
}
for (const row of input.rows.filter(row => row.active)) {
  total += row.amount
}
return { names, total }

let total = 0
for (let i = 0; i < 4; i++) {
  total += i
}
for (let j = 1; j <= 3; j++) {
  total += j
}
return { total }

let total = 0
for (let i = 0; i < input.items.length; i++) {
  if (i == 1) {
    continue
  }
  total += i
}
return { total }

let n = 3
const seen = json.array({ itemType: { type: "integer" } })
for (let i = 1; i <= n; i++) {
  if (i == 1) {
    n = 5
    continue
  }
  seen.push(i)
}
return { seen }

try {
