  result.count = failure.details.count
}

const kept = json.array({ itemType: { type: "integer" } })
for (const item of input.items) {
  if (item < 2) {
    continue
  }
  kept.push(item)
}
return { kept }

try {
  result.ok = true
} catch (failure) {
  if (failure.code != "SMTP_UNAVAILABLE") {
    throw failure
  }
  result.queued = true
}

try {
  throw { code: "FIRST", message: "first" }
