  try {
    result.value = JSON.parse(input.text)
  } catch (other) {
    throw failure
  }
}

const ids = input.rows.map(row => row.id)
const cards = input.rows.map(row => ({ id: row.id, name: row.name }))
return { ids, cards }

const byScore = input.rows.toSorted((a, b) => a.score - b.score)
const top = input.rows.toSorted((a, b) => b.score - a.score)
return { byScore, top }

const sorted = input.rows.toSorted((a, b) => a.name.localeCompare(b.name))
const reversed = input.rows.toSorted((a, b) => b.name.localeCompare(a.name))
return { sorted, reversed }

const numbers = input.values.toSorted((a, b) => a - b)
const words = input.names.toSorted((a, b) => a.localeCompare(b))
const texts = input.names.toSorted((a, b) => String(a).localeCompare(String(b)))
return { numbers, words, texts }

const sorted = input.rows.toSorted((a, b) => a.k < b.k ? -1 : (a.k > b.k ? 1 : 0))
const down = input.rows.toSorted((a, b) => b.k < a.k ? -1 : (b.k > a.k ? 1 : 0))
const same = input.rows.toSorted((a, b) => a.k <= b.k ? (a.k < b.k ? -1 : 0) : (a.k > b.k ? 1 : 0))
const items = input.values.toSorted((a, b) => a < b ? -1 : a > b ? 1 : 0)
return { sorted, down, same, items }

const sorted = input.rows.toSorted((a, b) => a.group.localeCompare(b.group) || b.score - a.score)
const stats = input.rows.toSorted((a, b) => (b.sumCents - a.sumCents) || (a.label < b.label ? -1 : a.label > b.label ? 1 : 0))
return { sorted, stats }

const names = input.rows.filter(row => row.active).map(row => row.name).join(", ")
const late = input.rows.filter(row => row.late).length
return { names, late }

const names = input.ok ? input.rows.filter(row => row.active).map(row => row.name) : []
const post = input.id !== null ? input.posts.find(p => p.id === input.id) : undefined
return { names, post, keys: input.o ? Object.keys(input.o) : [] }

const all = input.xs.concat(input.ys)
let items = []
for (const page of input.pages) {
  items = items.concat(page.rows.map(row => ({ id: row.id })))
}
return { all, items }

