const _flow = { sourceVersion: 3, inputs: { rows: { type: "array" } } }

function ConstLoop({ input, config, result }) {
  const doubled = json.array({ itemType: { type: "number" } })
  for (const item of input.rows) {
    const twice = item * 2
    if (twice > 0) {
      const shown = twice
      doubled.push(shown)
    }
  }
  let n = 0
  const steps = json.array({ itemType: { type: "number" } })
  while (n < 3) {
    const next = n + 10
    steps.push(next)
    n++
  }
  return { doubled, steps }
}

const _flow = { sourceVersion: 3, inputs: { csv: { type: "string" }, label: { type: "string" }, rows: { type: "array" } } }

function DefaultValues({ input, config, result }) {
  const csv = flow.default(input.csv, "")
  const names = input.rows.map(row => flow.default(row.name, "?"))
  const label = `[${flow.default(input.label, "none")}]`
  return { csv, names, label, empty: flow.default(input.csv, "") == "" }
}

const _flow = { sourceVersion: 3, inputs: { rows: { type: "array" } } }

function BlockScope({ input, config, result }) {
  let total = 0
  for (const row of input.rows) {
    const value = row * 2
    total += value
  }
  if (total > 0) {
    const value = 1
    total += value
  }
  const shown = json.array({ itemType: { type: "number" } })
  for (const value of input.rows) {
    shown.push(value)
  }
  return { total, shown }
}
